import { Chip, Card } from "march/ui"
import { heart } from "march/icons"

// pizzanı yap: her malzeme bir aç / kapa çip; seçilenin tiki yerine kalp çıkar, fiyat kendiliğinden toplanır
const toppings = [
  { name: "🍄 Mantar", price: 15 },
  { name: "🫒 Zeytin", price: 10 },
  { name: "🌶️ Biber", price: 8 },
  { name: "🧀 Ekstra peynir", price: 25 },
  { name: "🍍 Ananas", price: 20 },
]

export function PizzaBuilder() {
  let $picked = new Set(["🧀 Ekstra peynir"])
  const $total = 120 + toppings.filter((t) => $picked.has(t.name)).reduce((sum, t) => sum + t.price, 0)
  const toggle = (name: string) => { const n = new Set($picked); if (n.has(name)) n.delete(name); else n.add(name); $picked = n }
  return <Card title="Pizzanı yap" subtitle="Margarita tabanı · ₺120" m:color="brand-orange">
    <div sx={{ flex: ["row", "wrap"], gap: 2, mb: 3 }}>
      {toppings.map((t) => <Chip selected={$picked.has(t.name)} selectedIcon={heart} onClick={() => toggle(t.name)}>{t.name}</Chip>)}
    </div>
    <span sx={{ text: ["xl", "bold"], color: "brand-orange" }}>{`Toplam ₺${$total}`}</span>
  </Card>
}

import { Chip, Card, Button } from "march/ui"
import { tag } from "march/icons"

// sorun takipçisi: üstte durum süzgeçleri (aç / kapa çipler), altta kaldırılabilir etiketler ve yeni etiket ekleme;
// liste ikisine birden göre süzülür
const issues = [
  { title: "Giriş sayfası yavaş", status: "Açık", tags: ["performans"] },
  { title: "Karanlık temada düşük kontrast", status: "Bekliyor", tags: ["tasarım"] },
  { title: "Ödeme sonrası e-posta gitmiyor", status: "Açık", tags: ["e-posta"] },
  { title: "Profil fotoğrafı kırpılıyor", status: "Çözüldü", tags: ["tasarım"] },
]

export function IssueFilters() {
  let $statuses = new Set(["Açık", "Bekliyor"])
  let $labels = ["tasarım", "performans", "e-posta"]
  let $draft = ""
  const toggle = (s: string) => { const n = new Set($statuses); if (n.has(s)) n.delete(s); else n.add(s); $statuses = n }
  const add = () => { const t = $draft.trim().toLowerCase(); if (t && !$labels.includes(t)) $labels = [...$labels, t]; $draft = "" }
  const $shown = issues.filter((i) => $statuses.has(i.status) && i.tags.some((t) => $labels.includes(t)))
  return <Card title="Sorunlar">
    <div sx={{ flex: "col", gap: 3 }}>
      <div sx={{ flex: ["row", "wrap"], gap: 2 }}>
        {["Açık", "Bekliyor", "Çözüldü"].map((s) => <Chip tone="primary" selected={$statuses.has(s)} onClick={() => toggle(s)}>{s}</Chip>)}
      </div>
      <div sx={{ flex: ["row", "wrap", "center"], gap: 2 }}>
        {$labels.map((t) => <Chip icon={tag} size="sm" removeLabel={`${t} etiketini kaldır`} onRemove={() => $labels = $labels.filter((x) => x !== t)}>{t}</Chip>)}
        <form sx={{ flex: ["row", "center"], gap: 1 }} on:submit={(e: Event) => { e.preventDefault(); add() }}>
          <input bind:value={$draft} placeholder="Etiket ekle" aria-label="Yeni etiket" />
          <Button type="submit" size="sm" variant="secondary">Ekle</Button>
        </form>
      </div>
      <ul sx={{ flex: "col", gap: 1 }}>
        {$shown.length ? $shown.map((i) => <li>{`${i.title} · ${i.status}`}</li>) : <li sx={{ color: "muted" }}>Bu süzgeçlerle sorun yok</li>}
      </ul>
    </div>
  </Card>
}

import { test, expect, renderTest } from "march/testing"
import { ChipLab } from "./ChipLab.tsx"

// ChipLab'in testleri: kaydedince Testler sekmesinde çalışır
test("tone ve size sınıf olur; class çipe eklenir", () => {
  const s = renderTest(() => <ChipLab />)
  expect(s.find("danger")?.closest(".m-chip2")?.className.includes("m-chip2-danger")).toBe(true)
  expect(s.find("Küçük")?.closest(".m-chip2")?.className.includes("m-chip2-sm")).toBe(true)
  expect(s.get(".lab-new")?.className.includes("m-chip2")).toBe(true)
})

test("selected + onClick bir aç / kapa düğmesidir (aria-pressed)", async () => {
  const s = renderTest(() => <ChipLab />)
  const liked = await s.click("Beğenilen")
  expect(liked.getAttribute("aria-pressed")).toBe("true")
  expect(liked.closest(".m-chip2")?.className.includes("is-selected")).toBe(true)
  const starred = await s.click("Yıldızlı")
  expect(starred.getAttribute("aria-pressed")).toBe("false")
})

test("onRemove kaldırma düğmesini ekler; removeLabel onun adıdır", async () => {
  const s = renderTest(() => <ChipLab />)
  expect(s.sees("Ürün")).toBe(true)
  await s.click("Ürün etiketini sil")
  expect(s.sees("Ürün")).toBe(false)
  expect(s.find("Tasarım etiketini sil")?.tagName).toBe("BUTTON")
})

test("selected olmadan onClick de düğme yapar ve çağrılır", async () => {
  const s = renderTest(() => <ChipLab />)
  await s.click("Tıklandı: 0")
  expect(s.sees("Tıklandı: 1")).toBe(true)
})
